def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1

    foods1 = []
    foods2 = []
    foods3 = []
    for _ in range(N):
        v = int(data[idx]); idx += 1
        a = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        if v == 1:
            foods1.append((a, c))
        elif v == 2:
            foods2.append((a, c))
        else:
            foods3.append((a, c))

    def knapsack(foods):
        dp = [0] * (X + 1)
        for a, c in foods:
            for j in range(X, c - 1, -1):
                nv = dp[j - c] + a
                if nv > dp[j]:
                    dp[j] = nv
        return dp

    dp1 = knapsack(foods1)
    dp2 = knapsack(foods2)
    dp3 = knapsack(foods3)

    upper = min(dp1[X], dp2[X], dp3[X])

    def can(T):
        total = 0
        for dp in (dp1, dp2, dp3):
            if dp[X] < T:
                return False
            lo, hi = 0, X
            while lo < hi:
                mid = (lo + hi) // 2
                if dp[mid] >= T:
                    hi = mid
                else:
                    lo = mid + 1
            total += lo
            if total > X:
                return False
        return True

    lo, hi = 0, upper
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1

    print(lo)

