import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = ''.join(data[1:])
    L = 3 ** N

    cost0 = [0] * L   # min flips so subtree evaluates to 0
    cost1 = [0] * L   # min flips so subtree evaluates to 1
    val = [0] * L     # original evaluated value of subtree

    idx = 0
    for ch in A:
        if ch == '1':
            cost0[idx] = 1
            cost1[idx] = 0
            val[idx] = 1
        else:
            cost0[idx] = 0
            cost1[idx] = 1
            val[idx] = 0
        idx += 1

    n = L
    while n > 1:
        m = n // 3
        for i in range(m):
            j = i * 3
            a0, a1, a2 = cost0[j], cost0[j + 1], cost0[j + 2]
            b0, b1, b2 = cost1[j], cost1[j + 1], cost1[j + 2]

            # ---- make this node evaluate to 0 ----
            base = 0
            cnt = 0          # children forced to 0 for free (their cheaper option is 0)
            ex = []          # penalties to flip a "prefers 1" child to 0
            if a0 <= b0:
                base += a0; cnt += 1
            else:
                ex.append(a0 - b0)
            if a1 <= b1:
                base += a1; cnt += 1
            else:
                ex.append(a1 - b1)
            if a2 <= b2:
                base += a2; cnt += 1
            else:
                ex.append(a2 - b2)
            if cnt == 1:
                base += min(ex)
            elif cnt == 0:
                base += sum(ex) - max(ex)
            cost0[i] = base

            # ---- make this node evaluate to 1 ----
            base = 0
            cnt = 0
            ex = []
            if b0 <= a0:
                base += b0; cnt += 1
            else:
                ex.append(b0 - a0)
            if b1 <= a1:
                base += b1; cnt += 1
            else:
                ex.append(b1 - a1)
            if b2 <= a2:
                base += b2; cnt += 1
            else:
                ex.append(b2 - a2)
            if cnt == 1:
                base += min(ex)
            elif cnt == 0:
                base += sum(ex) - max(ex)
            cost1[i] = base

            # original majority value of the three children
            val[i] = 1 if (val[j] + val[j + 1] + val[j + 2]) >= 2 else 0

        n = m

    # answer = min flips to make root take the opposite of its current value
    if val[0] == 0:
        print(cost1[0])
    else:
        print(cost0[0])

