N = int(input())
grid = [['?' for _ in range(N)] for _ in range(N)]

for i in range(1, N + 1):
    j = N + 1 - i
    if i <= j:
        color = '#' if i % 2 == 1 else '.'
        for r in range(i, j + 1):
            for c in range(i, j + 1):
                grid[r - 1][c - 1] = color

for row in grid:
    print(''.join(row))
